changeSet.sql:
create table if not exists chats( id bigserial primary key, title varchar not null, type varchar not null, creator_id bigint, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table if not exists chat_members( id bigserial primary key, profile_id bigint not null, chat_id bigint not null references chats (id), profile_type varchar not null, user_name varchar not null, kicked boolean default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(profile_id, chat_id) );
create table if not exists messages( id bigserial primary key, message varchar, chat_id bigint not null references chats (id), chat_member_id bigint not null references chat_members (id), attachments jsonb, deleted boolean default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create table if not exists unread_messages( message_id bigint not null references messages (id), member_id bigint not null references chat_members (id), primary key(member_id, message_id) );
create table allowed_file_extensions ( id bigserial primary key, operation_name varchar not null, extension varchar not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
create or replace function add_unread_messages() returns trigger as $$ BEGIN insert into unread_messages (message_id, member_id) select NEW.id, unnest::bigint from unnest(array[ (select array_agg(id) from chat_members where chat_id = NEW.chat_id) ]); RETURN NEW; END; $$ language plpgsql;
CREATE TRIGGER add_unread_messages_trigger AFTER insert ON messages FOR EACH ROW EXECUTE PROCEDURE add_unread_messages();
create table chat_restrictions( id bigserial primary key, type varchar(50) not null unique, duration interval, "limit" int not null, description varchar, active bool default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
insert into chat_restrictions (type, duration, "limit") VALUES ('COUNT_CHAT_MESSAGES', interval '1 minute', 30)
